output_text:
[
  {
    "id": "get_cart_at_entrance_station",
    "text": "Shoppers must obtain their cart from the entrance cart station before shopping or exiting.",
    "abstraction": {
      "state_properties": {
        "entranceCartStation": "at(1,7)"
      },
      "events": {
        "getEntranceCart": {
          "pre": {
            "and": [
              "entranceCartStation",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "getEntranceCart"
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_narrow_aisle_mouth",
    "text": "A cart may be parked only at a designated mouth of a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "narrowAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "parked_cart_implies_cart_free_aisle_entry",
    "text": "After parking a cart at a narrow-aisle mouth, the shopper should enter the narrow shelf aisle without the cart.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "enterSingleFileWithoutCart"
    }
  },
  {
    "id": "return_to_cart_after_single_file_service",
    "text": "After taking an item from a single-file shelf aisle, the shopper must return to and reattach the parked cart.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "singleFileShelfService": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfService",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "reclaim_any_cart_parked_at_narrow_mouth",
    "text": "Any cart parked at the mouth of a narrow shelf aisle must be reclaimed before leaving.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "wide_shelf_service_with_cart",
    "text": "When an item is reachable from a wide shelf frontage, the shopper should service that shelf while keeping the cart.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "wideShelfFrontage": {
          "and": [
            "adjShelf",
            "wideAisle"
          ]
        }
      },
      "events": {
        "wideShelfService": {
          "pre": {
            "and": [
              "wideShelfFrontage",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfService",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Shoppers must not leave the store without their cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
